# owner: platform
import unittest

from rosterkit.notices import build_absence_notice
from rosterkit.models import Mark, Student
from datetime import date


def make_student():
    return Student("1001", "Thistle", "Bram", "A")


def make_mark(ident, month, status):
    return Mark(ident, date(2026, month, 5), status)


def mixed_marks():
    return [
        make_mark("1001", 11, "absent"),
        make_mark("1001", 9, "absent"),
        make_mark("1001", 10, "present"),
        make_mark("1001", 12, "excused")
    ]


def notice_for(marks):
    return build_absence_notice(make_student(), marks)


class NoticeTests(unittest.TestCase):
    def test_names_student_and_count(self):
        text = notice_for(mixed_marks())
        self.assertIn("Bram Thistle missed 2 days", text)

    def test_dates_are_in_order(self):
        text = notice_for(mixed_marks())
        self.assertIn("2026-09-05, 2026-11-05", text)

    def test_single_day_is_singular(self):
        text = notice_for([make_mark("1001", 9, "absent")])
        self.assertIn("missed 1 day ", text)

    def test_foreign_mark_is_rejected(self):
        marks = mixed_marks() + [make_mark("1002", 9, "absent")]
        with self.assertRaises(ValueError):
            notice_for(marks)

    def test_no_absences_is_rejected(self):
        with self.assertRaises(ValueError):
            notice_for([make_mark("1001", 9, "late")])

    def test_no_marks_is_rejected(self):
        with self.assertRaises(ValueError):
            notice_for([])
